/**
 * Compose
 * @description 组合中间件
 * @param middleWares
 * @constructor
 */
function Compose(middleWares) {
    return (ctx, next) => new Promise((resolve) => {
        let index = -1;
        // 中间件的返回值
        const middleWareQueueResults = Array.from({
            length: middleWares.length,
        }).fill(undefined);
        /**
         * loop
         * @description 迭代方法
         */
        const loop = () => {
            // 迭代完成了
            if (index + 1 >= middleWares.length) {
                Promise.all(middleWareQueueResults.filter((t) => t instanceof Promise)).then(() => {
                    // 真正的迭代完成
                    if (next) {
                        const p = next();
                        if (p && p.then) {
                            p.then(() => {
                                resolve();
                            });
                            return;
                        }
                    }
                    resolve();
                });
                return;
            }
            index++;
            // 调用中间件方法
            // @ts-ignore
            middleWareQueueResults[index] = middleWares[index](ctx, () => loop());
            return middleWareQueueResults[index];
        };
        loop();
    });
}
export default Compose;
